$('.price-type-radio').on('change', function() {
    var productId = $(this).data('product-id');
    var priceType = $(this).val();
    var isBulkBuyer = $(this).data('bulk-buyer') === 'true';

    var priceElement = $('#price-' + productId);
    var price = 0;

    // دریافت تمام داده‌های قیمت
    var bulkCashPrice = parseFloat($(this).data('bulk-cash-price')) || 0;
    var bulkCheckPrice = parseFloat($(this).data('bulk-check-price')) || 0;
    var retailCashPrice = parseFloat($(this).data('retail-cash-price')) || 0;
    var retailCheckPrice = parseFloat($(this).data('retail-check-price')) || 0;

    // تعیین قیمت بر اساس نوع کاربر و روش پرداخت
    if (isBulkBuyer) {
        if (priceType === 'cash') {
            price = bulkCashPrice;
        } else if (priceType === 'check') {
            price = bulkCheckPrice;
        }
    } else {
        if (priceType === 'cash') {
            price = retailCashPrice;
        } else if (priceType === 'check') {
            price = retailCheckPrice;
        }
    }

    // به‌روزرسانی قیمت با انیمیشن
    updatePriceDisplay(productId, price, priceElement);

    // به‌روزرسانی مجموع سبد خرید
    updateCartTotal();
});

function updatePriceDisplay(productId, price, priceElement) {
    // انیمیشن fade out
    priceElement.fadeOut(200, function() {
        // به‌روزرسانی قیمت
        var formattedPrice = formatPrice(price * 1000000);
        priceElement.text(formattedPrice + ' تومان');

        // انیمیشن fade in
        priceElement.fadeIn(200);
    });
}

function formatPrice(price) {
    return new Intl.NumberFormat('fa-IR').format(Math.round(price));
}

