@app.route('/add_to_cart', methods=['POST'])
@login_required
def add_to_cart():
    product_id = request.form.get('product_id')
    quantity = int(request.form.get('quantity', 1))
    price_type = request.form.get('price_type', 'cash')  # نوع قیمت جدید

    product = Product.query.get_or_404(product_id)

    # بررسی موجودی
    if product.stock_quantity < quantity:
        flash('موجودی کافی نیست', 'error')
        return redirect(url_for('shop'))

    # محاسبه قیمت بر اساس نوع کاربر و روش پرداخت
    if current_user.is_bulk_buyer:
        if price_type == 'cash':
            unit_price = product.bulk_price_cash
        else:
            unit_price = product.bulk_price_check
    else:
        if price_type == 'cash':
            unit_price = product.retail_price_cash
        else:
            unit_price = product.retail_price_check

    # بررسی وجود محصول در سبد خرید
    existing_item = CartItem.query.filter_by(
        user_id=current_user.id,
        product_id=product_id,
        price_type=price_type
    ).first()

    if existing_item:
        existing_item.quantity += quantity
    else:
        new_item = CartItem(
            user_id=current_user.id,
            product_id=product_id,
            quantity=quantity,
            unit_price=unit_price,
            price_type=price_type
        )
        db.session.add(new_item)

    db.session.commit()
    flash('محصول به سبد خرید اضافه شد', 'success')
    return redirect(url_for('shop'))

