@app.route('/create_invoice', methods=['POST'])
@login_required
def create_invoice():
    cart_items = CartItem.query.filter_by(user_id=current_user.id).all()

    if not cart_items:
        flash('سبد خرید خالی است', 'error')
        return redirect(url_for('cart'))

    # محاسبه مجموع بر اساس نوع قیمت هر محصول
    total_amount = 0
    for item in cart_items:
        total_amount += item.unit_price * item.quantity

    # ایجاد فاکتور
    invoice = Invoice(
        user_id=current_user.id,
        total_amount=total_amount,
        status='pending',
        payment_method='mixed'  # یا بر اساس انتخاب کاربر
    )
    db.session.add(invoice)
    db.session.flush()  # برای دریافت invoice.id

    # ایجاد آیتم‌های فاکتور
    for item in cart_items:
        invoice_item = InvoiceItem(
            invoice_id=invoice.id,
            product_id=item.product_id,
            quantity=item.quantity,
            unit_price=item.unit_price,
            price_type=item.price_type  # ذخیره نوع قیمت
        )
        db.session.add(invoice_item)

    # حذف آیتم‌های سبد خرید
    for item in cart_items:
        db.session.delete(item)

    db.session.commit()
    flash('فاکتور با موفقیت ایجاد شد', 'success')
    return redirect(url_for('invoice_detail', invoice_id=invoice.id))

