/* استایل‌های انتخاب نوع قیمت */
.price-selection-container {
    border: 1px solid #e9ecef;
    border-radius: 8px;
    padding: 10px;
    background: #f8f9fa;
}

.price-type-radio:checked + label {
    box-shadow: 0 0 0 0.2rem rgba(25, 135, 84, 0.25);
}

.price-type-radio:checked + label.btn-outline-success {
    background-color: #198754;
    border-color: #198754;
    color: white;
}

.price-type-radio:checked + label.btn-outline-warning {
    background-color: #fd7e14;
    border-color: #fd7e14;
    color: white;
}

/* انیمیشن تغییر قیمت */
.price-changing {
    opacity: 0.7;
    transform: scale(0.95);
    transition: all 0.15s ease-in-out;
}

.product-price-container {
    text-align: center;
    padding: 15px;
    border-radius: 8px;
    background: linear-gradient(135deg, #fff 0%, #f8f9fa 100%);
    border: 1px solid #e9ecef;
}

.price-savings {
    font-weight: 500;
    animation: pulse 2s infinite;
}

@keyframes pulse {
    0% { opacity: 1; }
    50% { opacity: 0.7; }
    100% { opacity: 1; }
}

/* بهبود دکمه‌های انتخاب */
.btn-group .btn {
    position: relative;
    overflow: hidden;
}

.btn-group .btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
    transition: left 0.5s;
}

.btn-group .btn:hover::before {
    left: 100%;
}
